content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #d1d5db;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 600px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 20px;
  text-align: center;
  color: var(--text-main);
}

.input-group {
  margin-bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-main);
}

.input {
  width: 100%;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s;
}

.input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.btn {
  width: 100%;
  padding: 12px;
  font-size: 1rem;
  font-weight: 600;
  color: #ffffff;
  background-color: var(--primary-color);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s;
  margin-top: 8px;
}

.btn:hover {
  background-color: var(--primary-hover);
}

.result-section {
  margin-top: 24px;
  padding: 16px;
  background-color: #eff6ff;
  border-radius: 8px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.bmi-value {
  font-size: 2rem;
  font-weight: 800;
  color: var(--primary-color);
}

.bmi-judge {
  font-size: 1.125rem;
  font-weight: 700;
}

.history-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 300px;
  overflow-y: auto;
}

.history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px;
  background-color: #f9fafb;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 0.9rem;
}

@media (max-width: 480px) {
  body {
    padding: 10px;
  }
  .card {
    padding: 16px;
  }
}

export interface BmiRecord {
  id: string;
  height: number;
  weight: number;
  bmi: number;
  judge: string;
  date: string;
}

import { useState, useEffect } from 'react';
import { BmiRecord } from './types';
import './index.css';

export default function App() {
  const [height, setHeight] = useState<string>('');
  const [weight, setWeight] = useState<string>('');
  const [currentResult, setCurrentResult] = useState<{ bmi: number; judge: string } | null>(null);

  const [history, setHistory] = useState<BmiRecord[]>(() => {
    const saved = localStorage.getItem('bmi_history');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('bmi_history', JSON.stringify(history));
  }, [history]);

  const calculateBmi = (e: React.FormEvent) => {
    e.preventDefault();
    const h = parseFloat(height);
    const w = parseFloat(weight);

    if (!h || !w || h <= 0 || w <= 0) return;

    const heightInMeters = h / 100;
    const bmiValue = w / (heightInMeters * heightInMeters);
    const roundedBmi = Math.round(bmiValue * 10) / 10;

    let judge = '';
    if (roundedBmi < 18.5) {
      judge = '低体重（やせ）';
    } else if (roundedBmi < 25) {
      judge = '普通体重';
    } else if (roundedBmi < 30) {
      judge = '肥満（1度）';
    } else if (roundedBmi < 35) {
      judge = '肥満（2度）';
    } else if (roundedBmi < 40) {
      judge = '肥満（3度）';
    } else {
      judge = '肥満（4度）';
    }

    setCurrentResult({ bmi: roundedBmi, judge });

    const newRecord: BmiRecord = {
      id: Date.now().toString(),
      height: h,
      weight: w,
      bmi: roundedBmi,
      judge,
      date: new Date().toLocaleDateString('ja-JP', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
      })
    };

    setHistory([newRecord, ...history]);
  };

  const clearHistory = () => {
    setHistory([]);
    localStorage.removeItem('bmi_history');
  };

  return (
    <div className="app-container">
      <div className="card">
        <h1 className="title">BMI 計算ツール</h1>
        <form onSubmit={calculateBmi}>
          <div className="input-group">
            <label className="label" htmlFor="height">身長 (cm)</label>
            <input
              id="height"
              className="input"
              type="number"
              step="0.1"
              placeholder="例: 170"
              value={height}
              onChange={(e) => setHeight(e.target.value)}
              required
            />
          </div>
          <div className="input-group">
            <label className="label" htmlFor="weight">体重 (kg)</label>
            <input
              id="weight"
              className="input"
              type="number"
              step="0.1"
              placeholder="例: 65"
              value={weight}
              onChange={(e) => setWeight(e.target.value)}
              required
            />
          </div>
          <button type="submit" className="btn">計算する</button>
        </form>

        {currentResult && (
          <div className="result-section">
            <div className="bmi-value">BMI: {currentResult.bmi}</div>
            <div className="bmi-judge">判定: {currentResult.judge}</div>
          </div>
        )}
      </div>

      {history.length > 0 && (
        <div className="card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
            <h2 className="title" style={{ margin: 0, fontSize: '1.25rem' }}>計算履歴</h2>
            <button
              onClick={clearHistory}
              style={{
                background: 'transparent',
                border: 'none',
                color: '#ef4444',
                cursor: 'pointer',
                fontSize: '0.875rem',
                fontWeight: '600'
              }}
            >
              履歴をクリア
            </button>
          </div>
          <ul className="history-list">
            {history.map((item) => (
              <li key={item.id} className="history-item">
                <div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{item.date}</div>
                  <div>身長: {item.height}cm / 体重: {item.weight}kg</div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <div style={{ fontWeight: 'bold', color: 'var(--primary-color)' }}>BMI: {item.bmi}</div>
                  <div style={{ fontSize: '0.85rem', fontWeight: '600' }}>{item.judge}</div>
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
